window.OSHA_QUESTIONS_SET2 = [
  { id: "in-16", category: "intro", topic: "Misión", q: "La misión de OSHA es:", choices: ["Cobrar impuestos a los contratistas", "Asegurar condiciones de trabajo seguras y saludables para las personas que trabajan", "Emitir permisos de construcción", "Reemplazar la compensación para trabajadores"], a: 1, why: "OSHA establece y hace cumplir normas, ofrece capacitación y asistencia, y exige un lugar de trabajo libre de peligros graves reconocidos." },
  { id: "in-17", category: "intro", topic: "Cobertura", q: "OSHA federal cubre en general:", choices: ["A todos los empleados públicos en todos los estados de forma automática", "A la mayoría de los empleadores del sector privado y sus trabajadores en estados sin State Plan", "Solo a empresas de construcción con 50+ empleados", "Solo a agencias federales"], a: 1, why: "La cobertura del sector privado es amplia. Los trabajadores estatales y locales están cubiertos solo en estados con State Plan. Los autoempleados en general no están cubiertos." },
  { id: "in-18", category: "intro", topic: "No cubiertos", q: "¿Qué grupo en general no está cubierto por la OSH Act?", choices: ["Trabajadores de almacén en un distribuidor privado", "Personas autoempleadas sin empleados", "Empleados de una planta de manufactura", "Peones de construcción en un trabajo privado"], a: 1, why: "Las personas autoempleadas, los familiares inmediatos en granjas pequeñas y algunos trabajadores cubiertos por otras agencias federales tienen cobertura limitada o nula de OSHA." },
  { id: "in-19", category: "intro", topic: "Acceso a SDS", q: "Los trabajadores tienen derecho a:", choices: ["Safety Data Sheets e información sobre los químicos con los que trabajan", "Las declaraciones de impuestos del empleador", "Los expedientes internos de personal de OSHA", "Saltarse la capacitación de peligros"], a: 0, why: "HazCom y la OSH Act dan a los trabajadores acceso a SDS, a registros de exposición en muchos casos y a sus propios registros médicos relacionados con el trabajo." },
  { id: "in-20", category: "intro", topic: "Rechazar trabajo", q: "Un trabajador puede rechazar una tarea cuando:", choices: ["No le cae bien el supervisor", "Tiene una creencia razonable de muerte inminente o lesión grave, no hay tiempo suficiente para que OSHA inspeccione, y ha pedido al empleador que lo corrija si es posible", "Se exigen horas extras", "El EPP es del color equivocado"], a: 1, why: "El rechazo es un derecho estrecho. Reporte el peligro, pida la corrección y no abandone todo el trabajo sin seguir los criterios." },
  { id: "in-21", category: "intro", topic: "Recorrido de inspección", q: "Durante una inspección de OSHA, un representante de los trabajadores:", choices: ["No tiene ningún papel", "Puede acompañar al inspector en el recorrido", "Debe quedarse en la oficina", "Solo puede hablar si el empleador está de acuerdo"], a: 1, why: "La Ley prevé la representación de los empleados en el recorrido de inspección." },
  { id: "in-22", category: "intro", topic: "Intencional (willful)", q: "Una infracción intencional (willful) es una cometida:", choices: ["Por accidente sin conocimiento", "Con desprecio intencional, o indiferencia clara, de los requisitos", "Solo después de una fatalidad", "Solo por un trabajador, nunca por un empleador"], a: 1, why: "Las citaciones willful llevan las multas más altas. Las reincidentes y la falta de corrección (failure-to-abate) son otras clasificaciones graves." },
  { id: "in-23", category: "intro", topic: "Grave", q: "Existe una infracción grave cuando:", choices: ["Un peligro podría causar muerte o daño físico grave y el empleador sabía o debió haber sabido", "Un cartel está un poco chueco", "Solo hay papeleo atrasado sin peligro", "Un trabajador fue grosero con un inspector"], a: 0, why: "Grave = probabilidad sustancial de muerte o daño grave, y conocimiento del empleador (real o constructivo)." },
  { id: "in-24", category: "intro", topic: "Cartel", q: "El empleador debe exhibir el cartel de OSHA de seguridad y salud en el trabajo:", choices: ["Solo en el congelador del comedor", "En un lugar visible donde los empleados puedan verlo", "Solo después de una citación", "Solo en línea, nunca en una pared"], a: 1, why: "El cartel de OSHA (o el equivalente estatal) debe publicarse donde los trabajadores puedan leerlo." },
  { id: "in-25", category: "intro", topic: "Corrección (abatement)", q: "Abatement significa:", choices: ["Solo pagar la multa", "Corregir el peligro citado para la fecha de la citación", "Impugnar cada partida de forma automática", "Despedir al trabajador lesionado"], a: 1, why: "El empleador debe corregir los peligros para la fecha de abatement o impugnar. No corregir trae multas adicionales." },
  { id: "in-26", category: "intro", topic: "Múltiples empleadores", q: "En una obra de construcción con varios empleadores, OSHA puede citar:", choices: ["Solo al dueño de la propiedad", "Al empleador que expone, crea, corrige y/o controla, según los hechos", "Solo al trabajador que se lastimó", "A nadie si hay un contratista general"], a: 1, why: "La política de múltiples empleadores de OSHA puede imponer deberes a más de un contratista. El empleador que controla (a menudo el GC) tiene el deber especial de mantener la obra razonablemente segura." },
  { id: "in-27", category: "intro", topic: "Conferencia de apertura", q: "Una inspección de OSHA suele comenzar con:", choices: ["Solo una conferencia de cierre", "Una conferencia de apertura que explica el motivo y el alcance", "Una citación sorpresa sin conversación", "Un examen médico de cada trabajador"], a: 1, why: "Los inspectores presentan credenciales, explican por qué están allí y describen el recorrido. Luego hay una conferencia de cierre." },
  { id: "in-28", category: "intro", topic: "Variaciones", q: "Un empleador que no puede cumplir por completo una norma puede solicitar:", choices: ["Una variación, demostrando protección equivalente", "Una exención permanente de toda OSHA", "Una licencia para saltarse la capacitación", "Una tarjeta que reemplaza las inspecciones"], a: 0, why: "Las variaciones temporales o permanentes requieren prueba de protección equivalente o mayor. No son un atajo alrededor de la seguridad." },
  { id: "in-29", category: "intro", topic: "Presentación 11(c)", q: "Una queja de denunciante bajo la Sección 11(c) en general debe presentarse ante OSHA dentro de:", choices: ["24 horas", "30 días", "1 año", "5 años"], a: 1, why: "Las quejas 11(c) suelen vencer a los 30 días del acto de represalia. Otros estatutos de denunciante pueden tener plazos distintos." },
  { id: "in-30", category: "intro", topic: "Consultoría", q: "La consultoría en el sitio de OSHA (On-Site Consultation):", choices: ["Emite citaciones igual que el cumplimiento", "Es un programa gratuito y confidencial para empleadores pequeños y medianos que no emite citaciones", "Es solo para sindicatos", "Reemplaza la necesidad de una tarjeta OSHA 10"], a: 1, why: "La consultoría es aparte del cumplimiento. El empleador debe corregir los peligros graves que identifiquen los consultores." },
  { id: "ff-08", category: "focusFour", topic: "Ejemplo de caída", q: "¿Cuál es un peligro de caída desde altura?", choices: ["Un borde de techo sin resguardo a 12 pies sobre el nivel del suelo", "Un gato de tarimas en el piso de un almacén al nivel del suelo sin desnivel", "Un muelle de 30 pulgadas bien resguardado con una cadena", "Sentarse en una silla"], a: 0, why: "Los lados y bordes sin protección a 6 pies o más en construcción requieren protección contra caídas." },
  { id: "ff-09", category: "focusFour", topic: "Golpes por vehículo", q: "Un trabajador en una zona de trabajo en la vía está más en riesgo de:", choices: ["Golpes (struck-by) por vehículos públicos o de construcción", "Atrapamiento en un archivero", "Cortes de papel de oficina", "Solo electrocución por escalera"], a: 0, why: "La ropa de alta visibilidad, los vigías, las barreras y el control de tráfico reducen los golpes en zonas de trabajo." },
  { id: "ff-10", category: "focusFour", topic: "Objeto que vuela", q: "Las herramientas de carga explosiva y las esmeriladoras pueden crear:", choices: ["Solo ruido, nunca proyectiles", "Golpes (struck-by) por sujetadores o fragmentos que vuelan", "Derrumbes de zanja", "Solo estrés por calor"], a: 1, why: "Use la carga correcta, protectores, protección de ojos/cara y nunca dispare hacia las personas." },
  { id: "ff-11", category: "focusFour", topic: "Atrapamiento en máquina", q: "Las partes rotatorias sin resguardo, los puntos de pellizco de entrada y las bandas transportadoras son principalmente:", choices: ["Peligros de caída", "Peligros de atrapamiento", "Peligros químicos", "Peligros de radiación"], a: 1, why: "El bloqueo, los resguardos y mantener el cuerpo fuera del punto de operación evitan muertes por aplastamiento y enredo." },
  { id: "ff-12", category: "focusFour", topic: "Atrapamiento en zanja", q: "Un trabajador en una zanja de 7 pies sin protección está expuesto a:", choices: ["Atrapamiento por derrumbe", "Solo golpes (struck-by) por herramientas", "Solo ruido", "Ningún peligro Focus Four"], a: 0, why: "El suelo es pesado. Una yarda cúbica puede pesar más que un auto. Los sistemas de protección no son opcionales." },
  { id: "ff-13", category: "focusFour", topic: "Carga aérea", q: "Caminar bajo una carga suspendida es:", choices: ["Aceptable si camina rápido", "Un peligro de golpes (y aplastamiento) que está prohibido", "Requerido para guiar la carga", "Seguro solo con casco"], a: 1, why: "El casco no detiene una viga de acero. Manténgase fuera de la zona de caída." },
  { id: "ff-14", category: "focusFour", topic: "Líneas aéreas", q: "Levantar una escalera o una pluma cerca de una línea aérea es principalmente un peligro de:", choices: ["Atrapamiento", "Electrocución", "Sílice", "Ruido"], a: 1, why: "Mantenga 10 pies (o más) de distancia, use vigías y considere desenergizar las líneas." },
  { id: "ff-15", category: "focusFour", topic: "GFCI", q: "La protección GFCI en la energía temporal de construcción reduce principalmente:", choices: ["Caídas", "Electrocución y choque", "Enfermedad por calor", "Derrumbes"], a: 1, why: "Los GFCI disparan con una pequeña corriente de falla a tierra antes de un choque letal en muchos casos. No reemplazan el aislamiento ni el bloqueo." },
  { id: "ff-16", category: "focusFour", topic: "Prevención de caídas", q: "El control preferido en construcción para el borde de un techo es:", choices: ["Esperar que los trabajadores recuerden amarrarse", "Un barandal u otro sistema convencional que proteja a todos", "Un memorando", "Solo pintar el borde de amarillo"], a: 1, why: "Los controles de ingeniería (barandales) protegen incluso si alguien olvida el arnés." },
  { id: "ff-17", category: "focusFour", topic: "Zona de caída", q: "Para reducir los peligros de golpes por objetos que caen:", choices: ["Rodapiés, redes de escombros, marquesinas y mantener a las personas fuera de la zona de caída", "Solo cascos sin otros controles", "Trabajar de noche", "Demolición más rápida"], a: 0, why: "1926.501/502: protección contra objetos que caen más barricadas abajo." },
  { id: "fp-17", category: "fallProtection", topic: "Borde de avance", q: "Un borde de avance (leading edge) es:", choices: ["El borde de un piso, techo o cimbra que cambia de lugar a medida que se colocan secciones nuevas", "Cualquier pared", "Un pretil terminado", "Solo el nariz de un peldaño"], a: 0, why: "El trabajo en borde de avance es de alto riesgo de caída. Se exige protección convencional o una alternativa documentada a 6 pies." },
  { id: "fp-18", category: "fallProtection", topic: "Residencial", q: "Para construcción residencial, OSHA espera actualmente:", choices: ["Ninguna protección contra caídas bajo 15 pies", "Protección convencional contra caídas a 6 pies salvo que se use una alternativa válida bajo la Subparte M", "Solo protectores de deslizamiento para siempre como único sistema", "Cinturones de cuerpo para detención"], a: 1, why: "OSHA canceló la antigua directiva residencial que permitía más alternativas. La protección convencional a 6 pies es la base." },
  { id: "fp-19", category: "fallProtection", topic: "Barandal intermedio", q: "Si no hay una pared de al menos 21 pulgadas de alto, un sistema de barandal necesita un barandal intermedio aproximadamente:", choices: ["A mitad de camino entre el barandal superior y la superficie de circulación", "A 6 pulgadas", "A 60 pulgadas", "Solo en andamios"], a: 0, why: "Los barandales intermedios quedan a unas 21 pulgadas cuando el superior está a 42. Las mallas o miembros intermedios pueden sustituir si cumplen la norma." },
  { id: "fp-20", category: "fallProtection", topic: "Barandales de cable de acero", q: "El banderín en un barandal de cable de acero se usa para:", choices: ["Aumentar la resistencia a 5,000 lb", "Hacer el riel más visible", "Reemplazar la necesidad de un barandal superior", "Poner a tierra el sistema"], a: 1, why: "Se exige banderín de alta visibilidad al menos cada 6 pies en rieles de cable de acero para que la gente vea el borde." },
  { id: "fp-21", category: "fallProtection", topic: "Eslinga", q: "Una eslinga con absorbedor de impacto está diseñada para:", choices: ["Eliminar toda la distancia de caída", "Reducir la fuerza de detención sobre el cuerpo", "Reemplazar un anclaje", "Atarse siempre alrededor de un barandal como anclaje preferido"], a: 1, why: "Conozca la distancia de desaceleración. Deje suficiente holgura para no golpear el nivel de abajo." },
  { id: "fp-22", category: "fallProtection", topic: "Holgura", q: "Antes de usar PFAS usted debe calcular:", choices: ["Solo el costo del arnés", "La holgura de caída: caída libre + desaceleración + altura del trabajador + margen de seguridad frente al nivel inferior", "Solo la pendiente del techo", "Solo la velocidad del viento"], a: 1, why: "Una eslinga de 6 pies puede necesitar unos 18+ pies de holgura con el paquete absorbedor, el estiramiento del arnés y la altura del anillo D. Los SRL cambian el cálculo." },
  { id: "fp-23", category: "fallProtection", topic: "SRL", q: "Una línea de vida autorretráctil (SRL) en general:", choices: ["Permite una caída libre de 30 pies", "Se traba rápido para limitar la caída libre, a menudo a 2 pies o menos según la unidad", "Reemplaza la necesidad de inspeccionar", "Puede envolverse sobre un borde filoso sin clasificación para borde de avance"], a: 1, why: "Use SRL clasificados para la aplicación (incluido borde de avance). Inspeccione y siga al fabricante." },
  { id: "fp-24", category: "fallProtection", topic: "Rescate", q: "Después de una detención de caída, el empleador debe tener:", choices: ["Ningún plan; el 911 siempre basta por sí solo", "Un plan de rescate inmediato: el trauma por suspensión puede matar", "Un plan solo para techos de más de 50 pies", "Que los trabajadores se corten ellos mismos"], a: 1, why: "1926.502(d)(20): rescate inmediato. No deje a un trabajador colgando. Capacite y prepare la recuperación." },
  { id: "fp-25", category: "fallProtection", topic: "Tragaluces", q: "Los tragaluces se tratan como:", choices: ["Adornos, no huecos", "Huecos que deben resguardarse o cubrirse; las personas caen a través de ellos", "Seguros para caminar si se ven gruesos", "Exentos bajo 15 pies"], a: 1, why: "Los tragaluces sin resguardo son una fatalidad clásica. Póngales malla, cubierta o barandal." },
  { id: "fp-26", category: "fallProtection", topic: "Aberturas en paredes", q: "Las aberturas en paredes desde las que hay una caída de más de 6 pies y la abertura mide al menos 30 pulgadas de alto y 18 pulgadas de ancho en general necesitan:", choices: ["Nada", "Protección con barandal", "Solo cinta de precaución", "Un letrero a 100 pies"], a: 1, why: "1926.501(b)(14): proteja las aberturas en paredes. Se incluyen las aberturas de ventanas durante la construcción." },
  { id: "fp-27", category: "fallProtection", topic: "Rampas", q: "Las rampas y pistas a 6 pies o más sobre un nivel inferior necesitan:", choices: ["Protección contra caídas como barandales", "Solo pintura antideslizante", "Nada si las usan carretillas", "Un 2x4 de un lado"], a: 0, why: "1926.501(b)(5): las rampas, pistas y otras pasarelas requieren protección a 6 pies." },
  { id: "fp-28", category: "fallProtection", topic: "Áreas de izaje", q: "En un área de izaje, los empleados deben estar protegidos de:", choices: ["Solo ruido", "Caer y ser golpeados por objetos; el barandal puede tener una cadena/puerta removible durante el aterrizaje", "Nada durante el aterrizaje de material", "Solo el clima"], a: 1, why: "1926.502(b)(3) y 501(b)(3): proteja el borde. Las cadenas deben cumplir la resistencia de barandal cuando están cerradas." },
  { id: "fp-29", category: "fallProtection", topic: "Albañilería en voladizo", q: "Una zona de acceso controlado para albañilería en voladizo usa una línea de control en general:", choices: ["A 3 pies del borde", "A 10 a 15 pies del borde de trabajo", "A 50 pies del borde", "Solo a nivel del suelo"], a: 1, why: "1926.502(k): 10–15 pies, con acceso limitado a albañiles. Es un sistema alternativo con límites estrictos, no un libertinaje." },
  { id: "fp-30", category: "fallProtection", topic: "Conectores compatibles", q: "Los mosquetones y anillos D deben ser:", choices: ["Cualquier herraje de la caja de herramientas", "Compatibles; mosquetones de doble seguro; no conectados de vuelta a la eslinga salvo según el diseño", "Atados en nudos", "Siempre dos ganchos en un anillo D"], a: 1, why: "1926.502(d): las conexiones incompatibles pueden soltarse (roll-out). Siga al fabricante." },
  { id: "fp-31", category: "fallProtection", topic: "Después de una caída", q: "Un arnés o eslinga que detuvo una caída debe:", choices: ["Reutilizarse después de un vistazo", "Retirarse de servicio", "Lavarse y devolverse el mismo día siempre", "Usarse como cinturón de posicionamiento"], a: 1, why: "Los paquetes absorbedores y las cintas son dispositivos de detención de un solo uso salvo que el fabricante indique otra cosa después de la inspección por una persona competente." },
  { id: "fp-32", category: "fallProtection", topic: "Anclaje improvisado", q: "¿Cuál es un mal anclaje?", choices: ["Un anclaje de techo diseñado de 5,000 lb", "Una fascia de 2x4, un barandal estándar o un tubo de PVC", "Un miembro de acero estructural clasificado por una persona calificada", "Un dálvita de ingeniería"], a: 1, why: "Nunca se amarre a un barandal, un conduit o algo que falle o corte la eslinga. El anclaje debe cumplir 502(d)(15)." },
  { id: "fp-33", category: "fallProtection", topic: "Posicionamiento", q: "Un sistema de dispositivo de posicionamiento debe impedir una caída libre de más de:", choices: ["6 pies", "2 pies", "12 pies", "30 pies"], a: 1, why: "1926.502(e): el posicionamiento limita la caída libre a 2 pies. No sustituye la detención de caídas cuando usted puede caerse del trabajo." },
  { id: "fp-34", category: "fallProtection", topic: "Línea de vida vertical", q: "Cada empleado en una línea de vida vertical en general necesita:", choices: ["Compartir un agarre de soga con un compañero", "Su propia línea de vida independiente", "Ningún agarre de soga", "Un cinturón de cuerpo"], a: 1, why: "1926.502(d)(10): una persona por línea de vida vertical salvo que el sistema esté diseñado de otro modo." },
  { id: "fp-35", category: "fallProtection", topic: "Línea de vida horizontal", q: "Las líneas de vida horizontales deben ser diseñadas por:", choices: ["Cualquier capataz", "Una persona calificada, con un factor de seguridad de al menos dos", "El aprendiz más nuevo", "OSHA durante la inspección"], a: 1, why: "La flecha, el claro y el número de usuarios cambian las fuerzas de forma dramática. Esto no es un proyecto de ferretería." },
  { id: "fp-36", category: "fallProtection", topic: "Techo empinado", q: "En un techo empinado (pendiente mayor de 4:12), las líneas de advertencia:", choices: ["Son un sustituto completo de la protección convencional", "No son el sistema usado en techos empinados: use protección convencional (barandales, redes o PFAS)", "Se exigen a 3 pies", "Reemplazan los rodapiés"], a: 1, why: "Los sistemas de línea de advertencia en 502(f) son para techado de pendiente baja. Los techos empinados necesitan sistemas convencionales." },
  { id: "ld-13", category: "ladders", topic: "Espaciado de peldaños", q: "Los peldaños de escaleras fijas y portátiles se espacian en general entre:", choices: ["4 y 6 pulgadas", "10 y 14 pulgadas", "18 y 24 pulgadas", "30 y 36 pulgadas"], a: 1, why: "1926.1053(a)(3): 10–14 pulgadas. Se exige espaciado uniforme." },
  { id: "ld-14", category: "ladders", topic: "Clasificación de servicio", q: "La clasificación de servicio de una escalera debe:", choices: ["Ignorarse si sube despacio", "Ser al menos el peso combinado del usuario más herramientas y materiales", "Ser solo para la escalera vacía", "Ser la mitad del peso del usuario"], a: 1, why: "Las clasificaciones Tipo IAA, IA, I, II, III son del fabricante/ANSI. OSHA exige no exceder la capacidad." },
  { id: "ld-15", category: "ladders", topic: "Mirar hacia la escalera", q: "Al subir una escalera usted debe:", choices: ["Mirar hacia la escalera", "Mirar hacia afuera y deslizarse", "Saltar peldaños para ir más rápido", "Llevar una hoja de plywood con ambas manos"], a: 0, why: "Mire hacia la escalera, use contacto de tres puntos y, si hace falta, suba materiales con una soga." },
  { id: "ld-16", category: "ladders", topic: "Peldaño superior de extensión", q: "El peldaño superior de una escalera extensible debe:", choices: ["Usarse como plataforma para pararse", "No usarse como peldaño; quédese por debajo del límite del fabricante", "Ser la posición de trabajo preferida", "Sostener a dos trabajadores"], a: 1, why: "No se pare en la tapa de una escalera de tijera ni en los peldaños superiores de una extensible más allá de la etiqueta." },
  { id: "ld-17", category: "ladders", topic: "Asegurar", q: "Las escaleras deben:", choices: ["Colocarse sobre cajas para ganar altura", "Estar en un apoyo estable y nivelado y asegurarse cuando se usen de modos que puedan desplazarlas", "Apoyarse en una pila de barriles", "Pintarse para ocultar defectos"], a: 1, why: "1926.1053(b): suelo firme y nivelado, no sobre objetos inestables. Asegure la parte superior o que alguien sujete la base cuando se necesite." },
  { id: "ld-18", category: "ladders", topic: "Hechas en la obra", q: "Las escaleras hechas en la obra deben:", choices: ["Usar cualquier madera de desperdicio", "Cumplir los requisitos de construcción de 1926.1053 (listones, relleno, ensamble dado, etc.)", "Ser solo de metal", "Tener peldaños a 24 pulgadas"], a: 1, why: "Las escaleras hechas en la obra se permiten si se construyen según la norma. Los peldaños clavados sin bloques de relleno fallan." },
  { id: "ld-19", category: "ladders", topic: "Abatimiento de puerta", q: "Si una escalera se coloca frente a una puerta:", choices: ["Siempre está bien", "La puerta debe bloquearse abierta, con llave o resguardarse para que no golpee la escalera", "Una nota en la puerta basta", "Solo se exigen conos"], a: 1, why: "Una puerta que se abre tira a las personas de las escaleras. Controle la puerta." },
  { id: "ld-20", category: "ladders", topic: "Acceso al andamio", q: "El acceso a plataformas de andamio a más de 2 pies por encima o por debajo del punto de acceso en general requiere:", choices: ["Saltar", "Una escalera, torre de escalera, rampa o equivalente — no trepar las riostras", "Trepar las riostras en cruz", "Solo una soga"], a: 1, why: "1926.451(e): acceso adecuado. No trepe los marcos de extremo salvo que estén diseñados como escaleras." },
  { id: "ld-21", category: "ladders", topic: "Soleras", q: "Las patas de andamio sobre suelo deben descansar sobre:", choices: ["Solo tierra suave", "Placas de base y soleras u otra base firme adecuada", "Un solo ladrillo", "Bloques de concreto de lado como costumbre"], a: 1, why: "1926.451(c)(2): placas de base y soleras adecuadas. Los apoyos inestables causan colapsos." },
  { id: "ld-22", category: "ladders", topic: "Servicio ligero", q: "Un andamio de servicio ligero en general está clasificado para:", choices: ["25 psf", "50 psf", "75 psf", "Carga ilimitada"], a: 0, why: "1926.451: ligero 25, mediano 50, pesado 75 libras por pie cuadrado. No sobrecargue con tarimas de mampostería en un marco de servicio ligero." },
  { id: "ld-23", category: "ladders", topic: "Rodapiés de andamio", q: "Se exigen rodapiés en andamios cuando:", choices: ["Nunca", "Los empleados trabajan o pasan abajo y se necesita protección contra objetos que caen, en general a 10 pies y según se especifique", "Solo a más de 50 pies", "Solo en torres rodantes"], a: 1, why: "1926.451(h): protección contra objetos que caen — rodapiés, mallas, redes de escombros o marquesina, más barricadas abajo." },
  { id: "ld-24", category: "ladders", topic: "Torre rodante", q: "Antes de mover un andamio rodante (torre móvil):", choices: ["Deje a los trabajadores en la plataforma para ahorrar tiempo", "Retire o asegure los materiales; los trabajadores en general no deben viajar salvo que el andamio esté diseñado para ello", "Deje las ruedas sin traba", "Empuje lo más rápido posible"], a: 1, why: "1926.452(w): trabe las ruedas al estacionar, nivele, no viaje salvo que se permita, límites de altura-base." },
  { id: "ld-25", category: "ladders", topic: "Líneas eléctricas y andamio", q: "Los andamios cerca de líneas energizadas deben mantener:", choices: ["Ninguna distancia si es de madera", "Las distancias especificadas (a menudo 10 pies hasta 50 kV) o tener las líneas desenergizadas/reubicadas/aisladas", "3 pies", "El contacto está bien con botas de hule"], a: 1, why: "1926.451(f)(6): distancia a las líneas. Las líneas aisladas igual necesitan la distancia de aproximación requerida salvo personas calificadas." },
  { id: "ld-26", category: "ladders", topic: "Persona competente de andamio", q: "Una persona competente de andamio es alguien que:", choices: ["Tiene una tarjeta de presentación", "Puede identificar peligros y tiene autoridad para tomar medidas correctivas", "Solo lee el folleto", "Es el trabajador más alto"], a: 1, why: "Definición de 1926.32(f). Inspecciona, capacita según se exija y detiene el trabajo inseguro." },
  { id: "ld-27", category: "ladders", topic: "Andamio colgante de dos puntos", q: "Los andamios de suspensión de dos puntos (plataformas colgantes) requieren:", choices: ["Ninguna protección contra caídas si está sobre agua", "Protección contra caídas (típicamente PFAS independiente del andamio) y amarre adecuado de contrapesos/voladizos", "Solo un casco", "Soga de manila de cualquier edad"], a: 1, why: "1926.451(g)(1) y 1926.452(o): líneas de vida independientes, equipo clasificado y amarres. Los contrapesos deben ser diseñados y no de arena suelta." },
  { id: "ex-11", category: "excavation", topic: "Peso del derrumbe", q: "Una yarda cúbica de suelo puede pesar aproximadamente:", choices: ["50 libras", "Tanto como un auto pequeño (unas 3,000 libras o más según el suelo y la humedad)", "5 libras", "Lo mismo que el unicel"], a: 1, why: "Por eso un colapso entierra y aplasta. No puede sacar a alguien a mano a tiempo." },
  { id: "ex-12", category: "excavation", topic: "Tipo A", q: "El suelo Tipo A es:", choices: ["El menos estable", "Suelo cohesivo con resistencia a la compresión no confinada de 1.5 tsf o más, sin fisuras, vibración ni disturbio previo (y otros límites de Tipo A)", "Siempre arena", "Siempre Tipo C después de la lluvia"], a: 1, why: "El Tipo A no puede estar en capas sobre B/C de un modo que falle, y no puede haber sido disturbado previamente. Muchas obras en realidad no tienen Tipo A." },
  { id: "ex-13", category: "excavation", topic: "Tipo B", q: "El suelo Tipo B se inclina en general a no más de:", choices: ["3/4 : 1", "1 : 1 (45 grados) para talud simple de menos de 20 pies", "1.5 : 1", "Vertical"], a: 1, why: "Datos tabulados del Apéndice B. La grava angular y el limo a menudo se clasifican como B o C." },
  { id: "ex-14", category: "excavation", topic: "Escudo vs apuntalamiento", q: "Un escudo de zanja (caja de zanja):", choices: ["Soporta el suelo como puntales hidráulicos en todos los casos", "Protege a los trabajadores dentro de la caja; no impide un derrumbe fuera de la caja", "Permite trabajar por encima del tope de la caja sin protección", "Reemplaza la necesidad de una persona competente"], a: 1, why: "Quédese dentro del escudo. No trabaje fuera de los extremos. Aplican los datos tabulados y las clasificaciones de profundidad del fabricante." },
  { id: "ex-15", category: "excavation", topic: "Altura de la caja", q: "La parte superior de una caja de zanja debe extenderse:", choices: ["Al menos 18 pulgadas por encima del suelo circundante si hay posibilidad de desprendimiento hacia la caja, según la práctica del fabricante/datos tabulados", "2 pulgadas bajo el nivel del suelo siempre", "Al ras y nunca por encima", "10 pies por encima"], a: 0, why: "Los fabricantes suelen exigir que la caja se extienda por encima del labio de la zanja para que el material excavado no entierre a los trabajadores. Siga los datos tabulados." },
  { id: "ex-16", category: "excavation", topic: "Escalera en la zanja", q: "Una escalera usada para salir de la zanja debe:", choices: ["Estar a no más de 25 pies de los trabajadores y extenderse por encima del descanso según se exija", "Colocarse sobre el montón de material excavado", "Ser de aluminio junto a los servicios siempre", "Ser opcional a 6 pies"], a: 0, why: "Combine 1926.651(c)(2) con las reglas de escaleras: extensión de 3 pies, asegurada, ángulo adecuado." },
  { id: "ex-17", category: "excavation", topic: "Vibración", q: "El equipo pesado o el tráfico cerca de una zanja:", choices: ["Mejora la resistencia del suelo", "Puede reducir la estabilidad del suelo; la persona competente debe evaluar", "Se exige para compactar las paredes", "Significa Tipo A de forma automática"], a: 1, why: "La vibración puede cambiar la clasificación y exigir más protección o más distancia." },
  { id: "ex-18", category: "excavation", topic: "Sobrecarga", q: "Los montones de material excavado, el equipo y los materiales cerca del borde crean:", choices: ["Una sobrecarga que puede provocar el colapso", "Protección extra", "Suelo Tipo A", "Un medio de salida"], a: 0, why: "Mantenga mínimo 2 pies de distancia y considere más para equipo pesado. Use dispositivos de contención si está más cerca." },
  { id: "ex-19", category: "excavation", topic: "Después de la lluvia", q: "Después de una tormenta, las excavaciones deben:", choices: ["Entrarse de inmediato para bombear a mano", "Reinspeccionarse por una persona competente antes de que los trabajadores vuelvan a entrar", "Darse por más seguras porque el suelo está compactado", "Estar exentas de talud"], a: 1, why: "1926.651(k)(1): inspeccione después de cada suceso que aumente el peligro, incluida la lluvia." },
  { id: "ex-20", category: "excavation", topic: "Atmósfera peligrosa", q: "Las excavaciones cerca de alcantarillas, rellenos sanitarios o tanques pueden tener:", choices: ["Solo oxígeno extra", "Deficiencia de oxígeno, gas inflamable o atmósferas tóxicas (H2S, CO, etc.)", "Ningún riesgo atmosférico bajo 20 pies", "Solo polvo"], a: 1, why: "Pruebe a 4 pies y según se necesite. Ventile. Debe considerarse el rescate de emergencia." },
  { id: "ex-21", category: "excavation", topic: "Extracción de agua", q: "Si se usa equipo de extracción de agua, debe:", choices: ["Quedar siempre sin atención", "Ser monitoreado por una persona competente", "Ser de gasolina dentro del hueco sin ventilación", "Tener documentación opcional"], a: 1, why: "1926.651(h)(2): la persona competente monitorea la extracción de agua para proteger a los empleados." },
  { id: "ex-22", category: "excavation", topic: "Rampa", q: "Una rampa estructural usada para acceso/salida debe:", choices: ["Ser diseñada por una persona competente (y un PE si es para vehículos, según se especifique)", "Ser cualquier talud de tierra", "Ser siempre más empinada de 45 grados", "Hacerse solo de plywood mojado"], a: 0, why: "1926.651(c)(1): rampas y pistas diseñadas por una persona competente; rampas para vehículos por un PE." },
  { id: "el-11", category: "electrical", topic: "Más de 50 kV", q: "Para líneas aéreas de más de 50 kV, la distancia de 10 pies en general aumenta en:", choices: ["1 pulgada por cada voltio extra", "4 pulgadas por cada 10 kV por encima de 50 kV", "10 pies por cada kV", "No se exige aumento"], a: 1, why: "1910.333(c)(3) / 1926.416: 10 pies + 4 pulgadas por cada 10 kV sobre 50 kV para personas no calificadas." },
  { id: "el-12", category: "electrical", topic: "AEGCP", q: "Un Programa asegurado de conductor de puesta a tierra del equipo (AEGCP) exige:", choices: ["Ninguna prueba", "Procedimientos escritos y pruebas especificadas de cordones y receptáculos (incluidas pruebas periódicas de continuidad)", "Solo una calcomanía de GFCI", "Pruebas una vez por década"], a: 1, why: "1926.404(b)(1)(iii): el AEGCP es la alternativa al GFCI. La mayoría de las obras simplemente usan GFCI." },
  { id: "el-13", category: "electrical", topic: "Doble aislamiento", q: "Una herramienta de doble aislamiento:", choices: ["Necesita un enchufe de tres patas", "Está marcada y puede usar un cordón de dos hilos; el sistema aislante reemplaza la tierra del equipo", "Puede usarse con la carcasa dañada", "Nunca necesita GFCI en una obra de construcción"], a: 1, why: "Busque la marca de caja dentro de caja. El daño a la carcasa destruye la protección. En construcción a menudo igual se exige GFCI en el receptáculo." },
  { id: "el-14", category: "electrical", topic: "Extensiones", q: "Los cordones flexibles en obras de construcción deben ser:", choices: ["Grapados a la madera con clavos de techo", "De tipo servicio pesado, no desgastados, y no usarse como sustituto del cableado fijo", "Cordón plano de dos hilos de una lámpara", "Pasados por puertas de modo que la puerta los aplaste"], a: 1, why: "1926.405/416: alivio de tensión, sin daño, tipo adecuado (S, ST, SO, etc.). No cuelgue del alambre ni pase por ventanas que corten el aislamiento." },
  { id: "el-15", category: "electrical", topic: "GFCI en mojado", q: "En lugares mojados, la iluminación portátil y las herramientas deben:", choices: ["Estar siempre sin tierra", "Tener protección GFCI y estar listadas para el ambiente", "Cablearse con cordón de lámpara", "Dejarse encendidas toda la noche en agua estancada"], a: 1, why: "Agua más electricidad mata. Use listados para lugares mojados y GFCI." },
  { id: "el-16", category: "electrical", topic: "Destello de arco", q: "Un destello de arco (arc flash) puede:", choices: ["Solo dar cosquilleo", "Producir calor extremo, presión y quemaduras incluso sin contactar un conductor", "Ocurrir solo por encima de 15 kV", "Detenerse siempre solo con ropa de algodón"], a: 1, why: "Las personas calificadas usan prácticas tipo NFPA 70E, ropa FR y desenergización. OSHA 1910.269/333 abordan peligros relacionados." },
  { id: "el-17", category: "electrical", topic: "Luces temporales", q: "Las lámparas temporales deben:", choices: ["Ser bombillas descubiertas que los trabajadores puedan tocar", "Protegerse del contacto y la rotura (jaulas/resguardos)", "Cablearse con alambre de timbre", "Colgarse del cordón como método listado siempre"], a: 1, why: "1926.405(a)(2)(ii): resguardos en luces temporales. No las suspenda del cordón salvo que estén diseñadas para ello." },
  { id: "el-18", category: "electrical", topic: "Alivio de tensión", q: "Los cordones deben tener alivio de tensión para que:", choices: ["El enchufe se vea ordenado", "La tensión no se transmita a las uniones o terminales", "La pata de tierra se rompa primero", "El GFCI nunca dispare"], a: 1, why: "Las conexiones jaladas exponen conductores. Use tapas de cordón adecuadas." },
  { id: "el-19", category: "electrical", topic: "Sobrecorriente", q: "Los fusibles y los interruptores automáticos sirven para:", choices: ["Proteger el conductor y el equipo de la sobrecorriente", "Aumentar el voltaje", "Reemplazar la puesta a tierra", "Servir como dispositivos de bloqueo sin candado"], a: 0, why: "No sustituyen el LOTO. Apagar un breaker no es bloqueo salvo que esté bloqueado y verificado." },
  { id: "el-20", category: "electrical", topic: "Concreto mojado", q: "Trabajar con herramientas eléctricas de pie en agua o sobre concreto mojado:", choices: ["Es de bajo riesgo porque el concreto aísla", "Aumenta la gravedad del choque porque usted está bien aterrizado", "Se exige para probar el GFCI", "Solo importa para herramientas de 12 voltios"], a: 1, why: "El concreto, la tierra y el agua dan una trayectoria a tierra. Use GFCI y lugares secos para pararse." },
  { id: "el-21", category: "electrical", topic: "Unión (bonding)", q: "El conductor de puesta a tierra del equipo debe:", choices: ["Cortarse para ahorrar tiempo", "Ser continuo y estar conectado para que las envolventes y los marcos de herramientas no se energicen sin detectarse", "Ser el alambre blanco", "Ser opcional en cajas de metal"], a: 1, why: "Una tierra faltante es un choque esperando una falla. Pruebe los cordones en un AEGCP o reemplace el equipo dañado." },
  { id: "el-22", category: "electrical", topic: "Aproximación", q: "Los trabajadores no calificados no deben acercarse más de la distancia requerida a:", choices: ["Circuitos desenergizados, bloqueados, etiquetados y probados", "Partes energizadas expuestas", "Taladros a batería", "Cable de fibra óptica"], a: 1, why: "Manténgase atrás. Solo personas calificadas con EPP y procedimientos adecuados trabajan cerca de partes vivas." },
  { id: "el-23", category: "electrical", topic: "GFCI de generador", q: "Los generadores portátiles usados en construcción para herramientas de 120 voltios:", choices: ["Nunca necesitan GFCI", "A menudo requieren GFCI en receptáculos de 15/20 amperios bajo la norma eléctrica de construcción", "Deben usarse en un cuarto cerrado para el silencio", "Deben unirse solo a una toma de incendio"], a: 1, why: "Siga 1926.404 y las instrucciones del fabricante. El escape es un asesino de CO en interiores." },
  { id: "el-24", category: "electrical", topic: "Agua y electricidad", q: "Si un compañero está recibiendo un choque y sigue en contacto con la fuente, usted debe:", choices: ["Agarrarlo con las manos desnudas", "Desenergizar o separarlo con un objeto aislado; no se convierta en una segunda víctima", "Echarle agua", "Jalar el alambre con la mano"], a: 1, why: "Corte la energía primero si puede. Llame a emergencias. RCP si está capacitado una vez que sea seguro." },
  { id: "el-25", category: "electrical", topic: "Marcado", q: "El equipo eléctrico debe estar marcado con:", choices: ["El apodo del superintendente", "Fabricante, voltaje, corriente y otras clasificaciones según se exija", "Solo un código QR", "Nada si está pintado"], a: 1, why: "1910.303(e) / 1926.403: marcados. Use el equipo dentro de su listado y clasificación." },
  { id: "pp-16", category: "ppe", topic: "Pies", q: "El calzado de puntera de seguridad suele seleccionarse según:", choices: ["Clasificaciones ANSI/ASTM de impacto y compresión para el peligro", "Solo la moda", "El acero más barato sin importar el ajuste", "Punta abierta para ventilación"], a: 0, why: "Empareje el peligro: impacto, compresión, perforación, peligro eléctrico (EH) y químico." },
  { id: "pp-17", category: "ppe", topic: "Casco Clase E", q: "Un casco Clase E está pensado para:", choices: ["Ninguna protección eléctrica", "Aislamiento eléctrico hasta 20,000 voltios (clase eléctrica estilo servicios)", "Solo soldadura", "Solo metal fundido"], a: 1, why: "Z89.1: Clase G (2,200 V), Clase E (20,000 V), Clase C (conductivo, sin eléctrico). Las clasificaciones eléctricas son del casco, no del trabajo en línea viva por sí solas." },
  { id: "pp-18", category: "ppe", topic: "Protectores laterales", q: "Cuando hay partículas que vuelan, la protección ocular debe:", choices: ["Usarse con protección lateral", "Ser lentes de moda tintados", "Ser opcional sobre lentes de contacto", "Ser solo careta sin lentes"], a: 0, why: "Protectores laterales o Z87 envolventes. Las caretas son además de, no en lugar de, la protección ocular primaria en muchas tareas." },
  { id: "pp-19", category: "ppe", topic: "Filtro de soldadura", q: "El tono del filtro de soldadura se selecciona según:", choices: ["El proceso y la corriente (números de tono en las tablas de OSHA/ANSI)", "Siempre el más oscuro disponible", "Ningún filtro si entrecierra los ojos", "Lentes claros solo para TIG"], a: 0, why: "Las tablas de 1926.102 / 1910.133 listan los tonos. Demasiado claro causa quemaduras; demasiado oscuro oculta el charco y causa mal trabajo/postura insegura." },
  { id: "pp-20", category: "ppe", topic: "NRR auditivo", q: "El NRR en protectores auditivos es:", choices: ["Una clasificación de laboratorio; la protección real a menudo es menor, y OSHA tiene un método de reducción", "La reducción de dB garantizada en campo para todos", "El PEL de ruido", "Solo para músicos"], a: 0, why: "El ajuste importa. OSHA 1910.95 Apéndice B reduce el NRR. La doble protección (tapones + orejeras) añade una reducción extra limitada." },
  { id: "pp-21", category: "ppe", topic: "APF", q: "El Factor de protección asignado (APF) de un respirador de media máscara con filtros es en general:", choices: ["5", "10", "50", "1,000"], a: 1, why: "1910.134 Tabla 1: media máscara APF 10, cara completa 50, PAPR media 50, PAPR de ajuste hermético de cara completa 1,000, etc. Aun así se exige prueba de ajuste para los de ajuste hermético." },
  { id: "pp-22", category: "ppe", topic: "IDLH", q: "En atmósferas IDLH, OSHA en general exige:", choices: ["Un tapabocas de polvo", "SCBA de demanda de presión de cara completa o SAR combinado con SCBA auxiliar de escape, y una persona de reserva", "Cualquier N95", "Solo uso voluntario"], a: 1, why: "1910.134(d)(2) y (g)(3): IDLH necesita la mayor protección respiratoria y capacidad de rescate." },
  { id: "pp-23", category: "ppe", topic: "Clase de alta visibilidad", q: "Las clases de alta visibilidad ANSI/ISEA 107 (1, 2, 3) se relacionan con:", choices: ["Cuánto material fluorescente de fondo y cinta retrorreflectante necesita según la velocidad/complejidad del tráfico", "Solo el color del casco", "Solo la resistencia a la flama", "La clasificación de detención de caídas"], a: 0, why: "El trabajo en vías a menudo exige Clase 2 o 3. Siga el MUTCD y el contrato." },
  { id: "pp-24", category: "ppe", topic: "Guantes anticorte", q: "Los guantes resistentes al corte se clasifican por:", choices: ["Niveles de corte ANSI/ISEA 105 (A1–A9) o equivalente", "Solo el color", "El grosor del algodón", "Si son de cuero"], a: 0, why: "Empareje la cuchilla y la tarea. Los guantes anticorte pueden no ser resistentes a perforación ni a químicos." },
  { id: "pp-25", category: "ppe", topic: "Recapacitación de EPP", q: "Se exige recapacitación de EPP cuando:", choices: ["El trabajador demuestra que no entiende, o cambian el lugar de trabajo/el EPP", "Nunca después de la capacitación inicial", "Solo si OSHA visita", "Cada hora"], a: 0, why: "1910.132(f)(3): cambios en el lugar de trabajo, el EPP o falta demostrada de conocimiento." },
  { id: "pp-26", category: "ppe", topic: "Receta", q: "Los trabajadores que usan lentes de receta en áreas de impacto necesitan:", choices: ["Solo lentes de calle", "Lentes de seguridad de receta Z87 o goggles/cubiertas que quepan encima", "Solo lentes de contacto", "Ninguna protección si tienen lentes"], a: 1, why: "Los lentes de moda no son lentes de seguridad. La protección lateral igual aplica." },
  { id: "pp-27", category: "ppe", topic: "Ajuste del arnés", q: "Un arnés de cuerpo completo debe ajustarse de modo que:", choices: ["El anillo D quede entre los omóplatos y las correas estén ceñidas sin cortar la circulación", "Cuelgue flojo por comodidad", "El anillo D quede en el pecho para todas las aplicaciones de detención", "Se omita la correa de pecho"], a: 0, why: "Anillo D dorsal para detención. Correa subpélvica en la posición correcta. Siga al fabricante." },
  { id: "hc-11", category: "hazcom", topic: "Elementos de etiqueta", q: "Una etiqueta GHS de recipiente enviado debe incluir:", choices: ["Identificador del producto, palabra de advertencia, indicaciones de peligro, pictogramas, consejos de prudencia e identificación del proveedor", "Solo un código de barras SKU", "Una calavera si el químico huele fuerte", "El cartel de OSHA"], a: 0, why: "1910.1200(f). Las etiquetas de trabajo pueden usar sistemas alternativos si transmiten la información requerida." },
  { id: "hc-12", category: "hazcom", topic: "Pictograma de salud", q: "El pictograma de peligro para la salud (silueta con un estallido en el pecho) cubre:", choices: ["Carcinógenos, mutágenos, tóxicos reproductivos, sensibilizantes respiratorios, peligros de órgano blanco y de aspiración", "Solo inflamabilidad", "Gases comprimidos", "Solo corrosión de la piel"], a: 0, why: "El pictograma de corrosión es para daño de piel/ojos y corrosión de metales. La calavera es toxicidad aguda." },
  { id: "hc-13", category: "hazcom", topic: "Llama sobre círculo", q: "El pictograma de llama sobre círculo significa:", choices: ["Oxidante", "Explosivo", "Gas comprimido", "Irritante"], a: 0, why: "Los oxidantes desprenden oxígeno e intensifican el fuego. Manténgalos lejos de combustibles." },
  { id: "hc-14", category: "hazcom", topic: "Signo de exclamación", q: "El pictograma de signo de exclamación puede indicar:", choices: ["Irritante, sensibilizante de la piel, toxicidad aguda (nocivo), efectos narcóticos o irritación de las vías respiratorias", "Siempre un carcinógeno", "Siempre un explosivo", "Ningún peligro"], a: 0, why: "Es el pictograma agudo “menos grave” comparado con la calavera." },
  { id: "hc-15", category: "hazcom", topic: "Sección 8", q: "La Sección 8 de la SDS suele cubrir:", choices: ["Primeros auxilios", "Controles de exposición y protección personal, incluidos los OEL", "Solo números UN de transporte", "Solo información ecológica"], a: 1, why: "Use la Sección 8 con las Secciones 2 y 4. Pueden listarse valores PEL/TLV; su sitio puede necesitar límites internos más bajos." },
  { id: "hc-16", category: "hazcom", topic: "Sección 4", q: "La Sección 4 de la SDS es:", choices: ["Medidas de primeros auxilios", "Combate de incendios", "Estabilidad", "Eliminación"], a: 0, why: "Conozca los primeros auxilios antes de usar el químico, no después del salpicón." },
  { id: "hc-17", category: "hazcom", topic: "Secreto comercial", q: "La identidad química reclamada como secreto comercial:", choices: ["Significa que no se exige SDS", "Aun así debe revelar los peligros; la identidad está disponible para profesionales de la salud en emergencias según se especifique", "Permite al empleador saltarse las etiquetas", "Aplica solo al agua"], a: 1, why: "1910.1200(i): los secretos comerciales tienen límites. El personal médico de emergencia puede obtener la identidad." },
  { id: "hc-18", category: "hazcom", topic: "No inglés", q: "La información de HazCom debe presentarse:", choices: ["Solo en inglés aunque nadie la entienda", "En un idioma y de un modo que los trabajadores comprendan, con SDS en inglés igual exigida en EE. UU.", "Solo como pictogramas sin capacitación", "Solo por mensaje de texto"], a: 1, why: "La capacitación debe ser comprensible. OSHA exige SDS en inglés; se pueden agregar otros idiomas." },
  { id: "hc-19", category: "hazcom", topic: "Tuberías", q: "Las tuberías sin etiqueta en un lugar de trabajo:", choices: ["Están exentas de cualquier deber de información", "Deben abordarse en el programa escrito (por ejemplo, con rótulos, diagramas de proceso o procedimientos)", "Siempre contienen agua", "Necesitan diamantes GHS cada 3 pies por regla federal en todas las plantas"], a: 1, why: "1910.1200(f)(6): el programa del empleador debe asegurar que los trabajadores conozcan el contenido y los peligros de las tuberías." },
  { id: "hc-20", category: "hazcom", topic: "Productos de consumo", q: "Los productos de consumo usados como en un hogar (misma duración/frecuencia) pueden estar:", choices: ["Siempre etiquetados por completo con etiquetas GHS de trabajo de todos modos", "Exentos de algunos requisitos de HazCom si se usan como lo haría un consumidor típico", "Prohibidos en las obras", "Obligados a tener SDS de 16 secciones pegada en el envase"], a: 1, why: "La exención de producto de consumo es estrecha. El uso industrial del mismo producto (más a menudo, más volumen) trae de vuelta el HazCom completo." },
  { id: "hc-21", category: "hazcom", topic: "Actualización de inventario", q: "Cuando llega un químico peligroso nuevo:", choices: ["Agregue la SDS y capacite según se necesite antes de que los trabajadores se expongan", "Espere un año", "Esconda la SDS", "Salte las etiquetas si el tambor es obvio"], a: 0, why: "Mantenga actualizados el inventario y la biblioteca de SDS. Capacite sobre los peligros nuevos." },
  { id: "hc-22", category: "hazcom", topic: "Códigos QR", q: "Un código QR en una etiqueta de trabajo:", choices: ["Puede complementar pero no debe ser la única forma de obtener la información requerida si los trabajadores no pueden acceder a él", "Reemplaza siempre todos los pictogramas", "Lo exige OSHA en cada envase", "Significa que el químico no es peligroso"], a: 0, why: "Las etiquetas deben funcionar cuando fallan los teléfonos y las redes. La información visual inmediata sigue importando." },
  { id: "lo-11", category: "loto", topic: "Tipos de energía", q: "¿Cuál es una fuente de energía peligrosa bajo LOTO?", choices: ["Solo electricidad de 480 voltios", "Eléctrica, mecánica, hidráulica, neumática, química, térmica, gravedad y radiación según aplique", "Solo vapor", "Solo gas natural"], a: 1, why: "Piense en todo lo que puede moverse, fluir, caer o quemarlo cuando se libera." },
  { id: "lo-12", category: "loto", topic: "Procedimiento", q: "Se exigen procedimientos de LOTO específicos de la máquina salvo que:", choices: ["El empleador nunca escriba nada", "Se cumpla la excepción limitada de 1910.147(c)(4)(i) (fuente única, fácilmente identificada, etc.)", "La máquina sea nueva", "Solo se usen etiquetas"], a: 1, why: "Las máquinas complejas o de múltiples fuentes necesitan pasos escritos específicos: notificar, apagar, aislar, bloquear, aliviar, verificar." },
  { id: "lo-13", category: "loto", topic: "Solo etiquetado", q: "El etiquetado sin candado se permite solo cuando:", choices: ["El empleador prefiere las etiquetas", "El dispositivo de aislamiento de energía no puede aceptar un candado, y se cumplen las disposiciones completas de etiquetado (incluida capacitación extra y protección equivalente)", "Es más rápido", "La etiqueta es roja"], a: 1, why: "1910.147(c)(3): se prefiere el bloqueo. Las etiquetas son advertencias, no sujeciones físicas." },
  { id: "lo-14", category: "loto", topic: "Dispositivo", q: "Un dispositivo de bloqueo debe ser:", choices: ["Estandarizado, identificable y usado solo para el control de energía", "Cualquier candado de la casa", "El mismo que un candado del almacén de herramientas", "Dejado sin llave con la llave puesta"], a: 0, why: "El color, la forma o el tamaño deben hacer obvios los candados de LOTO. Una llave por candado bajo el control del empleado autorizado." },
  { id: "lo-15", category: "loto", topic: "Cambio de turno", q: "Durante cambios de turno o de personal, el LOTO debe:", choices: ["Dejar la máquina sin bloqueo entre turnos", "Asegurar la continuidad de la protección: típicamente el empleado autorizado que llega aplica su candado antes de quitar el que sale", "Dejar que la producción arranque solo con etiquetas", "Saltar la verificación"], a: 1, why: "1910.147(e)(4): procedimientos específicos de cambio de turno. Nunca un hueco con cero candados." },
  { id: "lo-16", category: "loto", topic: "Probar la máquina", q: "Si debe energizar de forma temporal para probar:", choices: ["Deje todos los candados y espere", "Despeje la máquina, quite los candados según el procedimiento, energice, pruebe, luego desenergice y vuelva a aplicar LOTO antes de continuar el servicio", "Anule los resguardos para siempre", "Haga que un empleado afectado la arranque desde el comedor"], a: 1, why: "1910.147(f)(1): la reactivación temporal está estrictamente controlada." },
  { id: "lo-17", category: "loto", topic: "Contratistas", q: "Cuando los contratistas dan servicio al equipo, el anfitrión y el contratista deben:", choices: ["Ignorar los programas del otro", "Informarse mutuamente de sus procedimientos de bloqueo y coordinarse", "Usar solo los candados del contratista en el equipo del anfitrión sin comunicación", "Saltar el LOTO si la visita es corta"], a: 1, why: "1910.147(f)(2): personal externo. Los programas en conflicto causan arranques sobre personas." },
  { id: "lo-18", category: "loto", topic: "Producción normal", q: "Los cambios menores de herramienta y ajustes que son rutinarios, repetitivos e integrales a la producción pueden usar:", choices: ["Ninguna protección", "Medidas alternativas que den protección eficaz (nota de 1910.147(a)(2)(ii)) — no una excusa para saltarse el LOTO en un servicio de verdad", "Solo un gesto del supervisor", "La retirada de todos los resguardos"], a: 1, why: "La excepción de producción es estrecha. Si se mete en una máquina o anula un resguardo, está en territorio de LOTO." },
  { id: "lo-19", category: "loto", topic: "Liberación", q: "Antes de quitar los candados y restaurar la energía:", choices: ["Las herramientas y los trabajadores deben estar despejados, los resguardos reinstalados y los empleados afectados notificados", "Arranque la máquina para ver quién queda", "Quite primero el candado de la última persona mientras está adentro", "Salte la notificación"], a: 0, why: "1910.147(e): inspeccione el área de trabajo, notifique, luego quite su propio candado." },
  { id: "lo-20", category: "loto", topic: "Capacitación de autorizados", q: "Los empleados autorizados deben capacitarse sobre:", choices: ["El reconocimiento de fuentes de energía, el tipo y la magnitud, y los métodos de aislamiento y control", "Solo la declaración de misión de la empresa", "Cómo cortar candados", "La nómina"], a: 0, why: "1910.147(c)(7): los empleados autorizados, afectados y demás tienen distinta profundidad de capacitación." },
  { id: "lo-21", category: "loto", topic: "Recapacitación LOTO", q: "Se exige recapacitación de LOTO cuando:", choices: ["Hay un cambio en máquinas, procesos o procedimientos de control de energía, o una inspección revela lagunas", "Nunca", "Solo después de 20 años", "Solo para empleados afectados"], a: 0, why: "También recapacite cuando los trabajadores se desvíen del procedimiento." },
  { id: "lo-22", category: "loto", topic: "Hasp", q: "Un hasp de bloqueo permite:", choices: ["Que un candado bloquee 20 máquinas", "Que varios empleados autorizados apliquen sus propios candados en un punto de aislamiento", "Etiquetado sin candados siempre", "Que el supervisor conserve todas las llaves"], a: 1, why: "Cada persona permanece protegida hasta que quite su propio candado." },
  { id: "mh-16", category: "materials", topic: "Señales de mano", q: "Las señales de mano de grúa deben ser:", choices: ["Inventadas a diario", "Señales estándar de 1926 Subparte CC salvo que una persona de señales calificada use un sistema no estándar documentado", "Opcionales si usted grita", "Usadas solo de noche"], a: 1, why: "1926.1419–1422: persona de señales calificada cuando se exija. Los radios deben ser dedicados y probados." },
  { id: "mh-17", category: "materials", topic: "Doble bloqueo", q: "El doble bloqueo (two-blocking) es:", choices: ["Un método legal de izada", "Cuando el bloque del gancho golpea la punta de la pluma — puede romper el cable y soltar la carga", "Un tipo de estabilizador", "Una señal"], a: 1, why: "Los dispositivos anti-two-block se exigen en muchas grúas. Nunca los desactive." },
  { id: "mh-18", category: "materials", topic: "Viento", q: "El viento fuerte durante una izada de grúa:", choices: ["Puede exigir detener la izada según los límites del fabricante", "Mejora la capacidad", "Solo afecta a las grúas torre", "Se ignora si baja la pluma"], a: 0, why: "Las tablas de carga y los manuales listan límites de viento. La carga lateral en la pluma es peligrosa." },
  { id: "mh-19", category: "materials", topic: "Izada crítica", q: "Una izada crítica a menudo incluye:", choices: ["Cualquier carga de menos de 50 lb", "Varias grúas, izadas cerca de la capacidad o izadas sobre espacios ocupados — se exige planificación extra", "Levantar una caja de herramientas", "El recorrido de un montacargas en un pasillo de almacén"], a: 1, why: "Los empleadores y las prácticas ASME B30 exigen un plan de izada. OSHA Subparte CC exige precauciones extra para ciertas operaciones." },
  { id: "mh-20", category: "materials", topic: "Eslinga sintética", q: "Las eslingas de cinta sintética no deben:", choices: ["Protegerse de bordes filosos", "Anudarse, ahorcarse en un gancho sin gancho de eslinga, ni usarse si están cortadas, podridas por UV o derretidas", "Inspeccionarse", "Usarse dentro de la capacidad"], a: 1, why: "1926.251: no nudos. Los bordes cortan la cinta. Use protectores de desgaste." },
  { id: "mh-21", category: "materials", topic: "Eslinga de cable de acero", q: "Retire de servicio una eslinga de cable de acero cuando:", choices: ["Se vea brillante", "Haya kinks, aplastamiento, jaula de pájaro o conteos de alambres rotos más allá de la norma", "Se haya usado una vez", "La etiqueta siga puesta"], a: 1, why: "1926.251 y ASME B30.9: los criterios de alambres rotos dependen de la construcción. Nunca use una eslinga como ahorque si está dañada." },
  { id: "mh-22", category: "materials", topic: "Cinturón del montacargas", q: "En un montacargas contrapesado de sentado, el operador debe:", choices: ["Usar el cinturón de seguridad", "Nunca usar cinturón para poder saltar", "Pararse en las horquillas", "Elevar la carga para ver mejor al circular"], a: 0, why: "Volcadura: quédese en la cabina, inclinarse lejos de la caída, cinturón puesto. Saltar es cómo las personas quedan aplastadas." },
  { id: "mh-23", category: "materials", topic: "Carga en circulación", q: "Lleve una carga de montacargas:", choices: ["Alta e inclinada hacia atrás lo más posible siempre", "Baja, con el mástil inclinado hacia atrás, y las horquillas apenas lo bastante altas para despejar el piso", "En las puntas de las horquillas", "Mientras alguien viaja en la carga"], a: 1, why: "Triángulo de estabilidad. Las cargas altas vuelcan. No hay pasajeros en las horquillas salvo una plataforma de personal diseñada bajo las reglas." },
  { id: "mh-24", category: "materials", topic: "Peatones", q: "En áreas con peatones, los operadores de montacargas deben:", choices: ["Tocar el claxon en intersecciones, reducir la velocidad y nunca asumir que la gente los oye", "Conducir a velocidad de carretera", "Elevar la carga para advertir a la gente", "Enviar mensajes mientras conducen"], a: 0, why: "1910.178(n): reglas de tráfico, claxones, separe a los peatones cuando sea posible." },
  { id: "mh-25", category: "materials", topic: "PIT de propano", q: "Los montacargas de gas LP en interiores:", choices: ["No tienen problemas de ventilación", "Producen CO; necesitan ventilación y mantenimiento del sistema de combustible", "Están siempre prohibidos", "Pueden quedar en ralentí en un tráiler cerrado para calor"], a: 1, why: "Las intoxicaciones por CO ocurren en tráileres y cuartos fríos. Corte el combustible al estacionar según se exija." },
  { id: "mh-26", category: "materials", topic: "RPM de esmeriladora", q: "La clasificación de RPM de una rueda abrasiva debe ser:", choices: ["Menor que la velocidad de la esmeriladora para que gire más rápido", "Al menos tan alta como la velocidad de la máquina", "Ignorada en esmeriladoras portátiles", "La mitad de la velocidad de la máquina"], a: 1, why: "Una rueda de 6,000 RPM en una esmeriladora de 10,000 RPM puede reventar. Empareje las clasificaciones." },
  { id: "mh-27", category: "materials", topic: "Resguardos de herramientas", q: "Los resguardos de herramientas eléctricas:", choices: ["Pueden quitarse para ver mejor", "Deben permanecer en su lugar según el diseño", "Son opcionales después de OSHA 10", "Aplican solo a sierras de mesa"], a: 1, why: "1926.300 / 1910.212: resguardos puestos. Quitar el resguardo de una esmeriladora es una citación y lesión comunes." },
  { id: "hh-14", category: "health", topic: "Nivel de acción de sílice", q: "El nivel de acción de sílice es un TWA de 8 horas de:", choices: ["10 μg/m³", "25 μg/m³", "50 μg/m³", "100 μg/m³"], a: 1, why: "A o por encima de 25 μg/m³ aplican la vigilancia médica, la comunicación de peligros y otros elementos del programa según se especifique." },
  { id: "hh-15", category: "health", topic: "Barrido en seco de sílice", q: "El barrido en seco o el soplado con aire comprimido seco de polvo de sílice está:", choices: ["El método preferido", "En general prohibido donde existan alternativas factibles (métodos húmedos, aspiradora HEPA)", "Exigido por la Tabla 1", "Seguro si aguanta la respiración"], a: 1, why: "1926.1153(f): orden y limpieza. El aire comprimido para limpiar está muy restringido." },
  { id: "hh-16", category: "health", topic: "Médico de plomo", q: "El monitoreo de plomo en sangre forma parte de:", choices: ["La norma de plomo cuando las exposiciones llegan a los umbrales del nivel de acción", "Solo programas infantiles", "Solo etiquetas de HazCom", "Inspecciones de extintores"], a: 0, why: "1926.62 / 1910.1025: vigilancia médica, retiro a niveles especificados de plomo en sangre e instalaciones de higiene." },
  { id: "hh-17", category: "health", topic: "Asbesto Clase I", q: "El trabajo de asbesto Clase I es:", choices: ["Papeleo de oficina", "Retiro de TSI y ACM de superficie", "Siempre solo loseta de piso", "Manejar un camión"], a: 1, why: "1926.1101: la Clase I es el retiro más peligroso. La Clase II es otro retiro de ACM; la Clase III mantenimiento; la Clase IV limpieza de polvo." },
  { id: "hh-18", category: "health", topic: "Síntomas de CO", q: "Los síntomas tempranos de monóxido de carbono a menudo incluyen:", choices: ["Piel verde brillante", "Dolor de cabeza, mareo, náusea y confusión", "Solo tos años después", "Mejor rendimiento atlético"], a: 1, why: "Salga al aire fresco. Los detectores de CO en obras que usan calentadores y generadores salvan vidas." },
  { id: "hh-19", category: "health", topic: "Emergencia por calor", q: "Ante una sospecha de golpe de calor (caliente, confundido o inconsciente, puede dejar de sudar):", choices: ["Hágalo seguir trabajando a la sombra", "Llame al 911, enfríe rápido (hielo, agua, sombra) y no demore", "Dé solo tabletas de sal", "Espere una hora para ver"], a: 1, why: "El golpe de calor es una emergencia médica. Enfriar mientras espera al EMS es crítico." },
  { id: "hh-20", category: "health", topic: "WBGT", q: "Los programas de calor a menudo usan:", choices: ["Solo el enfriamiento por viento", "La Temperatura de globo de bulbo húmedo (WBGT) o el índice de calor más ciclos de trabajo/descanso", "Solo la temperatura del aire ignorando el sol", "Dosímetros de ruido"], a: 1, why: "La guía de calor de NIOSH/OSHA usa WBGT. Los TLV de ACGIH fijan trabajo/descanso según la carga de trabajo." },
  { id: "hh-21", category: "health", topic: "Viento frío", q: "El enfriamiento por viento aumenta:", choices: ["El estrés por calor", "La tasa de pérdida de calor y el riesgo de congelación", "La exposición a sílice", "El tiempo de disparo del GFCI"], a: 1, why: "Cubra la piel, manténgase seco, tome descansos para calentarse. La congelación puede ocurrir por encima de 0°F con viento y humedad." },
  { id: "hh-22", category: "health", topic: "PEL de cromo hexavalente", q: "El PEL de cromo hexavalente es un TWA de 8 horas de:", choices: ["5 μg/m³", "50 μg/m³", "500 μg/m³", "5 mg/m³"], a: 0, why: "1910.1026: 5 μg/m³. El humo de soldadura de inoxidable es una fuente común en construcción/industria general." },
  { id: "hh-23", category: "health", topic: "Cromo hexavalente en soldadura", q: "Para reducir el cromo hexavalente en la soldadura de inoxidable:", choices: ["Suelde en un tanque cerrado sin extracción", "Ventilación de extracción local, cambio de proceso y respiradores según se exija", "Solo un tapabocas de papel en la barbilla", "Más argón siempre elimina el hexavalente"], a: 1, why: "LEV en el penacho más protección respiratoria cuando se necesite. Los recubrimientos en el acero pueden ser peores que el metal base." },
  { id: "hh-24", category: "health", topic: "Benceno", q: "El benceno es:", choices: ["Un carcinógeno asociado con gasolina, solventes y algo de trabajo petroquímico", "Una vitamina", "Solo un polvo", "Inofensivo si huele dulce"], a: 0, why: "1910.1028: PEL estrictos, médico e higiene. No se lave las manos con gasolina." },
  { id: "hh-25", category: "health", topic: "Audiograma", q: "Un audiograma de línea base en un programa de conservación auditiva se obtiene en general:", choices: ["Dentro de 6 meses de la primera exposición en o por encima del nivel de acción (1 año si se usan unidades móviles, con protección auditiva mientras tanto)", "Después de 10 años", "Nunca", "Solo si el trabajador se queja"], a: 0, why: "1910.95: línea base y luego audiogramas anuales. El STS (cambio umbral estándar) activa el seguimiento." },
  { id: "hh-26", category: "health", topic: "Higiene de plomo", q: "En áreas de trabajo de plomo, los trabajadores no deben:", choices: ["Comer, beber ni usar tabaco en el área contaminada", "Lavarse las manos", "Usar ropa de protección", "Usar las instalaciones de higiene"], a: 0, why: "1926.62: áreas de cambio, duchas cuando se activen, y nada de comida en el área de trabajo para evitar la ingestión." },
  { id: "fr-11", category: "fire", topic: "Clase D", q: "Los incendios Clase D involucran:", choices: ["Papel", "Metales combustibles como magnesio o titanio", "Solo paneles energizados", "Aceite de cocina"], a: 1, why: "Use un polvo Clase D clasificado para ese metal. El agua puede empeorar los incendios de metal." },
  { id: "fr-12", category: "fire", topic: "Clase K", q: "Los extintores Clase K son para:", choices: ["Tarimas de madera", "Aceites y grasas de cocina comercial", "Solo gasolina", "Solo cuartos eléctricos"], a: 1, why: "Químico húmedo Clase K para freidoras. No use un químico seco Clase B como único plan de la cocina si se exige K." },
  { id: "fr-13", category: "fire", topic: "Distancia Clase B", q: "La distancia máxima de recorrido hasta un extintor Clase B es en general:", choices: ["25 pies", "50 pies", "75 pies", "150 pies"], a: 1, why: "1910.157(d)(4): 50 pies para Clase B." },
  { id: "fr-14", category: "fire", topic: "Tiempo de vigía de incendio", q: "Después de soldar o cortar donde se exige vigía de incendio, la vigilancia debe durar al menos:", choices: ["5 minutos", "30 minutos (y más si se necesita por brasas)", "2 horas siempre", "Hasta que el soldador salga del estacionamiento"], a: 1, why: "1910.252(a)(2)(iii): al menos 30 minutos. Algunas operaciones necesitan más." },
  { id: "fr-15", category: "fire", topic: "Gabinete inflamable", q: "Los gabinetes aprobados de almacenamiento de inflamables:", choices: ["Están diseñados para proteger el contenido de un incendio exterior durante un período", "Hacen que los líquidos no sean inflamables", "Reemplazan la puesta a tierra de los tambores", "Pueden dejarse abiertos con la puerta quitada"], a: 0, why: "1910.106: límites de cantidades fuera de gabinetes. Mantenga las puertas cerradas. La puesta a tierra/unión sigue importando al despachar." },
  { id: "fr-16", category: "fire", topic: "Punto de inflamación", q: "Un líquido inflamable (estilo Categoría 1–2 / antigua Clase I) tiene un punto de inflamación:", choices: ["En general bajo 100°F para Clase I según la definición antigua de OSHA", "Siempre por encima de 200°F", "De 0 K solamente", "Que no importa para el almacenamiento"], a: 0, why: "1910.106 usa el punto de inflamación y el de ebullición. Las categorías GHS difieren un poco; el peligro sigue siendo el fuego." },
  { id: "fr-17", category: "fire", topic: "Descarga de salida", q: "Una descarga de salida debe:", choices: ["Llevar a una calle, pasarela o espacio abierto con acceso al exterior", "Terminar en un patio cerrado sin salida", "Pasar por un cuarto de almacenamiento de combustibles como único camino", "Usarse para almacenar tarimas"], a: 0, why: "1910.34–37: el camino de salida sigue siendo salida hasta que esté a salvo afuera." },
  { id: "fr-18", category: "fire", topic: "Alarma", q: "Los sistemas de alarma para empleados deben ser:", choices: ["Distintivos y reconocibles como señal de evacuar o actuar", "Los mismos que la campana de descanso si conviene", "Opcionales con menos de 500 personas siempre", "Solo de texto"], a: 0, why: "1910.165 / 1910.38: todos deben conocer la alarma. Pruebe el sistema." },
  { id: "fr-19", category: "fire", topic: "Rociadores", q: "El almacenamiento de materiales debe mantenerse:", choices: ["Apilado contra las cabezas de rociadores", "Al menos 18 pulgadas bajo los deflectores de los rociadores (más para algunas reglas de almacenamiento extra alto)", "Tocando calentadores", "Frente a los extintores"], a: 1, why: "1910.159 y NFPA: holgura para que el agua pueda rociar. No cuelgue ropa en la tubería de rociadores." },
  { id: "fr-20", category: "fire", topic: "Trapos con aceite", q: "Los trapos empapados de aceite y solvente deben:", choices: ["Amontonarse en un rincón", "Colocarse en recipientes de metal con tapa para evitar la combustión espontánea", "Dejarse en el bolsillo de un trabajador", "Tirarse con el reciclaje de papel"], a: 1, why: "El aceite de linaza y algunos acabados se calientan al secar. Use botes listados para desperdicio aceitoso." },
  { id: "ww-08", category: "walking", topic: "Clasificación de carga", q: "Las superficies de trabajo y circulación deben poder soportar:", choices: ["La carga máxima prevista", "Solo el peso de una persona siempre", "Solo nieve", "La mitad de la carga prevista"], a: 0, why: "1910.22(b): las superficies, incluidas cubiertas y rejillas, deben soportar la carga. Los andamios y las cubiertas de huecos tienen factores extra." },
  { id: "ww-09", category: "walking", topic: "Placas de muelle", q: "Las placas de muelle (puentes) deben:", choices: ["Asegurarse para evitar que se deslicen y poder soportar la carga", "Hacerse de cartón", "Ser opcionales si el hueco es de 2 pies", "Usarse como sube y baja"], a: 0, why: "1910.30 / 1910.26: las placas de muelle portátiles y motorizadas tienen reglas específicas, incluida la prevención de salirse." },
  { id: "ww-10", category: "walking", topic: "Escaleras GI", q: "En industria general, el uso de escaleras portátiles incluye:", choices: ["Mirar hacia la escalera, contacto de tres puntos y no cargar cargas que causen una caída", "Pararse en la tapa de una escalera de tijera", "Usar una escalera de metal junto a barras colectoras vivas", "Empalmar dos escaleras con alambre"], a: 0, why: "1910.23: principios similares a la construcción 1926.1053." },
  { id: "ww-11", category: "walking", topic: "Nariz de peldaño", q: "Las escaleras estándar deben tener:", choices: ["Altura de contrahuella y profundidad de huella uniformes; nariz que no cree un tropiezo", "Alturas de contrahuella al azar para frenar a la gente", "Huecos abiertos de 20 pulgadas entre huellas", "Ningún pasamanos si las usan contratistas"], a: 0, why: "1910.25: ángulos especificados (típicamente 30–50 grados), uniformidad y barandales." },
  { id: "ww-12", category: "walking", topic: "Descenso por soga", q: "Los sistemas de descenso por soga en industria general (lavado de ventanas) en general requieren:", choices: ["Ninguna capacitación", "Capacitación, equipo inspeccionado, respaldo independiente y documentación del dueño del edificio de los anclajes", "Una sola soga sin inspeccionar", "Cinturones de cuerpo para detención"], a: 1, why: "1910.27: reglas de RDS después de varias fatalidades. Los anclajes deben estar certificados." },
  { id: "ww-13", category: "walking", topic: "Pisos mojados", q: "Cuando los pisos están mojados:", choices: ["Advierta, limpie, use tapetes y proporcione drenaje donde se exija", "Apague las luces", "Corra", "Guarde tarimas extra en el charco"], a: 0, why: "1910.22(a)(2): mantenga tan seco como sea posible; use drenaje, plataformas, tapetes o pisos falsos." },
  { id: "ww-14", category: "walking", topic: "Jaula de escalera GI", q: "Las escaleras fijas en industria general instaladas el 19 de noviembre de 2018 o después en general deben tener:", choices: ["Jaulas como el único sistema permitido para siempre", "Sistemas de seguridad de escalera o detención personal de caídas en lugar de jaulas para alturas de más de 24 pies, con un plazo de transición para escaleras más viejas", "Ninguna protección", "Solo una plataforma de descanso a 100 pies"], a: 1, why: "1910.28(b)(9): las jaulas se están eliminando como sistema primario en escaleras fijas." },
  { id: "ww-15", category: "walking", topic: "Orden y limpieza en construcción", q: "Los escombros de construcción deben:", choices: ["Retirarse a intervalos regulares para que no se acumulen y causen peligros", "Dejarse hasta el Certificado de Ocupación", "Empujarse a los huecos de escalera", "Quemarse en el edificio"], a: 0, why: "1926.25: la madera de cimbra y desperdicio con clavos salientes se mantiene despejada; recipientes para basura." },
  { id: "cs-01", category: "confined", topic: "Definición", q: "Un espacio confinado es un espacio que:", choices: ["Es lo bastante grande para entrar, tiene entrada/salida limitada y no está diseñado para ocupación continua", "Es cualquier cuarto con puerta", "Está solo bajo tierra", "Es cualquier excavación"], a: 0, why: "1910.146(b): los tres criterios. La construcción usa 1926 Subparte AA con conceptos similares." },
  { id: "cs-02", category: "confined", topic: "Que requiere permiso", q: "Un espacio confinado que requiere permiso tiene uno o más de:", choices: ["Atmósfera peligrosa, sepultamiento, paredes/pisos que convergen hacia adentro, o cualquier otro peligro grave de seguridad/salud", "Buena iluminación y dos puertas", "Una ventana", "Solo polvo que no es combustible"], a: 0, why: "Un PRCS necesita un programa escrito, permisos, vigías y planificación de rescate." },
  { id: "cs-03", category: "confined", topic: "Oxígeno", q: "El oxígeno aceptable para la entrada es en general:", choices: ["16.0% a 18.0%", "19.5% a 23.5%", "25% a 30%", "Cualquier nivel si se siente bien"], a: 1, why: "Por debajo de 19.5% hay deficiencia de oxígeno. Por encima de 23.5% hay enriquecimiento de oxígeno y peligro de incendio." },
  { id: "cs-04", category: "confined", topic: "Orden de prueba", q: "El orden de prueba atmosférica es típicamente:", choices: ["Tóxicos, luego oxígeno, luego inflamables", "Oxígeno, luego inflamable/explosivo, luego gases tóxicos", "Solo inflamables", "Lo que el medidor haga primero por accidente"], a: 1, why: "Nota de 1910.146(c)(5)(ii)(C): O2 primero (los medidores necesitan O2 para leer el LEL correctamente), luego LEL, luego tóxicos." },
  { id: "cs-05", category: "confined", topic: "LEL", q: "En general no se permite la entrada si el gas inflamable está en o por encima de:", choices: ["1% del LEL", "10% del LEL (para espacios con permiso salvo que aplique una excepción específica)", "100% LEL", "Solo el UEL"], a: 1, why: "1910.146(b) atmósfera peligrosa incluye gas inflamable sobre el 10% del LEL. Algunas industrias usan límites más estrictos." },
  { id: "cs-06", category: "confined", topic: "Vigía", q: "El trabajo del vigía es:", choices: ["Entrar a ayudar con herramientas", "Quedarse afuera, monitorear a los entrantes, mantener fuera a personas no autorizadas y convocar el rescate — no entrar a rescatar salvo que esté capacitado, relevado y equipado", "Irse si está lento", "Operar el proceso desde adentro"], a: 1, why: "Nunca abandone la vigilancia. Varios espacios necesitan procedimientos si un vigía cubre más de uno." },
  { id: "cs-07", category: "confined", topic: "Entrante", q: "Los entrantes autorizados deben:", choices: ["Ignorar el permiso", "Conocer los peligros, usar el equipo, comunicarse con el vigía y salir cuando se les indique o cuando noten un problema", "Quitarse el arnés por comodidad", "Probar la atmósfera solo después de sentirse mareados"], a: 1, why: "1910.146(h): deberes de los entrantes autorizados." },
  { id: "cs-08", category: "confined", topic: "Supervisor", q: "El supervisor de entrada:", choices: ["Firma el permiso, verifica las pruebas y el rescate, y también puede servir como vigía o entrante si está calificado", "Es solo un título en un organigrama", "Nunca visita el espacio", "Puede saltarse las pruebas atmosféricas"], a: 0, why: "1910.146(j): el supervisor autoriza la entrada y la termina cuando cambian las condiciones." },
  { id: "cs-09", category: "confined", topic: "Rescate", q: "El método de rescate preferido es:", choices: ["Compañeros sin capacitación que se meten corriendo", "Rescate sin entrada (línea de recuperación) siempre que no aumente el riesgo", "Esperar a ver si despiertan", "Llenar el espacio de oxígeno"], a: 1, why: "La mayoría de las muertes en espacios confinados son de rescatistas improvisados. Los malacates de recuperación y los arneses salvan vidas cuando los espacios verticales lo permiten." },
  { id: "cs-10", category: "confined", topic: "Empleador anfitrión", q: "Cuando un contratista entra a un espacio con permiso del anfitrión, el anfitrión debe:", choices: ["No decir nada sobre los peligros", "Informar al contratista del programa de permisos, los peligros y cualquier precaución", "Cancelar todos los permisos", "No dar información por razones de responsabilidad"], a: 1, why: "1910.146(c)(8) y (c)(9): deberes del anfitrión y del contratista en ambos sentidos después del trabajo." },
  { id: "cs-11", category: "confined", topic: "Reclasificar", q: "Un espacio con permiso puede reclasificarse como sin permiso solo cuando:", choices: ["Usted pone un letrero que lo dice", "Se eliminan todos los peligros reales o potenciales sin necesidad de aire forzado continuo (aislamiento, etc.) según se especifique", "El oxígeno es 20.8% una vez", "Se coloca un ventilador en la abertura sin evaluación"], a: 1, why: "1910.146(c)(7): la reclasificación se documenta y dura solo mientras los peligros sigan eliminados. La ventilación de aire forzado sola no reclasifica; puede permitir entrada alterna bajo (c)(5)." },
  { id: "cs-12", category: "confined", topic: "Entrada alterna", q: "Los procedimientos de entrada alterna (c)(5) aplican cuando:", choices: ["El único peligro es una atmósfera peligrosa real o potencial y el aire forzado continuo más las pruebas la mantienen segura", "Hay un peligro de sepultamiento", "Hay pisos inclinados hacia adentro que pueden atrapar", "Usted tiene prisa"], a: 0, why: "Si existen peligros de sepultamiento o de configuración, necesita el programa completo de permisos." },
  { id: "cs-13", category: "confined", topic: "Ventilación", q: "La ventilación de aire forzado para entrada alterna debe:", choices: ["Dirigirse a ventilar las áreas inmediatas donde están los empleados y continuar hasta que salgan", "Soplar desde el fondo de un pozo profundo sin un plan", "Usar oxígeno puro", "Funcionar solo 30 segundos antes de la entrada"], a: 0, why: "1910.146(c)(5): ventile, pruebe y mantenga el aire en movimiento desde una fuente limpia." },
  { id: "cs-14", category: "confined", topic: "Aislamiento", q: "El aislamiento de un espacio con permiso puede incluir:", choices: ["Cegar/cegar con brida, desalininear tuberías, doble bloqueo y sangrado, y bloqueo de energía", "Un cono frente a la escotilla", "Pedir a los operadores que no arranquen bombas", "Un letrero de papel en una válvula"], a: 0, why: "1910.146(b) define el aislamiento. El LOTO de mezcladores y transportadores forma parte de muchas entradas." },
  { id: "cs-15", category: "confined", topic: "Rótulos", q: "Los espacios con permiso a los que no se entra aun así deben:", choices: ["Ocultarse", "Identificarse con rótulos de peligro u otros medios igualmente eficaces", "Llenarse de agua", "Dejarse abiertos para el flujo de aire"], a: 1, why: "1910.146(c)(2): PELIGRO — ESPACIO CONFINADO QUE REQUIERE PERMISO — NO ENTRE o equivalente." },
  { id: "cs-16", category: "confined", topic: "Construcción AA", q: "Los espacios confinados de construcción están cubiertos por:", choices: ["Solo 1910.146 en cada trabajo", "29 CFR 1926 Subparte AA", "Ninguna norma", "Solo códigos estatales de construcción"], a: 1, why: "La Subparte AA (1926.1201–1213) es la regla de construcción. Es similar a 1910.146 con deberes específicos de anfitrión/contratista que controla." },
  { id: "cs-17", category: "confined", topic: "H2S", q: "El sulfuro de hidrógeno en alcantarillas y tanques es peligroso porque:", choices: ["Huele a flores a altas concentraciones", "Puede paralizar el olfato a concentraciones más altas y es altamente tóxico e inflamable", "Es inofensivo", "Siempre es más ligero que el aire así que nunca se acumula"], a: 1, why: "El H2S es más pesado que el aire y puede acumularse. No confíe en la nariz. Use un medidor." },
  { id: "cs-18", category: "confined", topic: "Sepultamiento", q: "El grano, la arena o el agua en un silo o pozo es un:", choices: ["Peligro de sepultamiento", "Solo un peligro de resbalón", "Solo un peligro eléctrico", "Solo un peligro de caída"], a: 0, why: "El material que fluye puede enterrar y asfixiar. Bloqueo de descargadores y uso de arneses/recuperación según se exija." },
  { id: "cs-19", category: "confined", topic: "Capacitación CS", q: "La capacitación de espacios confinados se exige:", choices: ["Antes de las funciones asignadas y cuando cambien los peligros o las funciones", "Una vez en la vida", "Solo para equipos de rescate", "Solo si ocurrió una fatalidad"], a: 0, why: "1910.146(g): capacite y documente que ocurrió la capacitación." },
  { id: "cs-20", category: "confined", topic: "Duración del permiso", q: "Un permiso de entrada debe:", choices: ["Conservarse hasta que la entrada termine y luego retenerse al menos 1 año", "Tirarse de inmediato", "Ser válido por 5 años de entradas", "Ser solo verbal"], a: 0, why: "1910.146(e)(6) y (f): cancele el permiso al terminar; revise los permisos cancelados dentro de 1 año para actualizar el programa." },
  { id: "cs-21", category: "confined", topic: "Síntomas tempranos", q: "Si un entrante se siente mareado o el medidor alarma:", choices: ["Termine los últimos cinco minutos de trabajo", "Evacue de inmediato", "Apague el medidor", "Mande al vigía adentro"], a: 1, why: "Salga ante alarma, ante una orden o ante cualquier síntoma. Reevalúe antes de que alguien vuelva." },
  { id: "cs-22", category: "confined", topic: "Recuperación", q: "Se exige un arnés de pecho o de cuerpo completo con línea de recuperación salvo que:", choices: ["Aumente el riesgo general o no ayude al rescate (por ejemplo, cierta tubería horizontal)", "Al trabajador no le gusten los arneses", "El espacio requiera permiso", "El vigía tenga un celular"], a: 0, why: "1910.146(k)(3): el equipo de rescate sin entrada es lo predeterminado. Documente las excepciones." },
  { id: "cs-23", category: "confined", topic: "Equipo de rescate", q: "Un servicio de rescate fuera del sitio debe:", choices: ["Ser el departamento de bomberos que nunca se ha capacitado en sus espacios y está a 45 minutos, sin evaluación", "Evaluarse por la capacidad de responder a tiempo y practicar con sus tipos de espacios", "Ser opcional si tiene un permiso", "Ser solo una compañía de grúas"], a: 1, why: "1910.146(k): evalúe el rescate. Invítenlos a practicar. El tiempo hasta el paciente importa: el daño cerebral empieza en minutos." },
  { id: "cs-24", category: "confined", topic: "Trabajo en caliente CS", q: "Soldar en un espacio confinado requiere:", choices: ["Ninguna regla extra", "Precauciones de trabajo en caliente más controles atmosféricos de espacio confinado; nunca use oxígeno para ventilar", "Oxígeno puro para “endulzar” el aire", "Cerrar todos los respiraderos"], a: 1, why: "1910.252 y 1910.146 se superponen. La inertización, el vigía de incendio y el aislamiento de gases son comunes." },
  { id: "cs-25", category: "confined", topic: "Rescatistas improvisados", q: "La mayoría de las fatalidades en espacios confinados a menudo son:", choices: ["Equipos de rescate capacitados con SCBA", "Rescatistas improvisados sin capacitación que entran después de la primera víctima", "Trabajadores de oficina", "Personas que usan malacates de recuperación correctamente"], a: 1, why: "No entre a salvar a alguien salvo que sea el equipo de rescate designado y equipado y haya otro vigía en su lugar." }
];
